int	item_find(const char *id)
{
	int	i;

	for (i = 0; i < g_nitems; i++)
		if (!strcmp(g_items[i].id, id))
			return (i);
	return (-1);
}

void	look_default(t_look *lk)
{
	static const char	*def[NSLOT] = {"fond_aucun", "cape_voyage",
		"jambes_jambieres", "armure_cotte", "casque_cabosse", "yeux_fente",
		"deco_plume", "arme_epee", "main_lanterne", "familier_aucun", "aura_aucune"};
	int					i;

	for (i = 0; i < NSLOT; i++)
	{
		lk->eq[i] = item_find(def[i]);
		lk->col[i] = 0;
	}
}

const t_coll	g_histoires[] = {
	{"fond_cite", "La grande caverne, telle que la voyaient les veilleurs : la Tour au loin, et ses fenêtres qui s'éteignaient une à une.", "The great cavern as the watchers saw it: the Tower in the distance, its windows going dark one by one."},
	{"fond_fonderie", "Les fours ne se sont jamais tout à fait refroidis. Pendant le Long Silence, la Fonderie a continué de chauffer pour personne.", "The furnaces never fully cooled. Through the Long Silence, the Foundry kept burning for no one."},
	{"fond_puits", "L'eau calme du fond du Puits. Les cordiers disaient qu'elle se souvenait de chaque ligne descendue.", "The still water at the bottom of the Well. The rope-walkers said it remembered every line they climbed down."},
	{"fond_nuit_tour", "Certaines nuits, une lune pâle passait derrière la Tour. Personne ne savait d'où venait cette lumière, si loin sous la surface.", "Some nights a pale moon drifted behind the Tower. No one knew where that light came from, so far below the surface."},
	{"cape_voyage", "La cape de celui qui arrive à la fin du Long Silence. Elle a pris la poussière de toutes les routes avant celle-ci.", "The cloak of the one who arrives at the end of the Long Silence. It carries the dust of every road before this one."},
	{"cape_lisiere", "Une cape trouvée à la lisière de la caverne, déchirée par les rouages qui tournaient à vide.", "A cloak found at the edge of the cavern, torn by gears that spun for nothing."},
	{"cape_brume", "Tissée dans la brume qui fuyait des murs. Elle ne pèse rien, et laisse passer le froid.", "Woven from the mist that leaked from the walls. It weighs nothing, and lets the cold through."},
	{"cape_format", "Les fondeurs en couvraient les moules pour qu'ils ne refroidissent pas trop vite. Elle sent encore le métal chaud.", "The founders draped it over the moulds so they would not cool too fast. It still smells of hot metal."},
	{"cape_veteran", "On ne l'achète pas. On la reçoit après être passé par la Fonderie et en être revenu.", "It cannot be bought. It is given to those who went through the Foundry and came back."},
	{"jambes_jambieres", "Des jambières simples, faites pour marcher longtemps sur la pierre sans faire de bruit.", "Plain greaves, made to walk a long time on stone without a sound."},
	{"jambes_bottes", "Les veilleurs les usaient en faisant le tour des rues, encore et encore, à attendre que quelqu'un vienne.", "The watchers wore them out walking the streets, again and again, waiting for someone to come."},
	{"jambes_greves", "Forgées pour les gardes de la Tour. Les gardes sont partis, les grèves sont restées debout dans un coin.", "Forged for the Tower guards. The guards left; the greaves were still standing in a corner."},
	{"armure_cotte", "Chaque maille a été refermée à la main. Il en manque quelques-unes : personne n'était là pour les remplacer.", "Every ring was closed by hand. A few are missing: no one was there to replace them."},
	{"armure_gambison", "Un vêtement rembourré, chaud et silencieux, que portaient ceux qui veillaient la nuit.", "A padded coat, warm and quiet, worn by those who kept watch at night."},
	{"armure_pierre", "Taillée dans les murs de la Tour, là où la mousse avait déjà commencé à pousser.", "Cut from the walls of the Tower, where the moss had already begun to grow."},
	{"armure_fonderie", "Rivetée à chaud par les fondeurs, pour travailler près des creusets sans se brûler.", "Hot-riveted by the founders, to work by the crucibles without getting burned."},
	{"casque_heaume", "Un heaume fermé, à fente étroite. Celui qui le porte voit peu, mais ne recule pas.", "A closed helm with a narrow slit. Whoever wears it sees little, but does not step back."},
	{"casque_capuche", "Les veilleurs la rabattaient sur leurs yeux quand la brume devenait trop épaisse pour y voir.", "The watchers pulled it over their eyes when the mist grew too thick to see through."},
	{"casque_pourcent", "Coulé dans un moule de la Fonderie, celui du signe qui annonce chaque forme. Il ne sert qu'aux vétérans.", "Cast in a Foundry mould, the one for the sign that announces every form. Only veterans wear it."},
	{"casque_veteran", "Le casque de ceux qui ont tenu jusqu'au bout de la Fonderie. Son or n'a pas terni.", "The helm of those who held on to the end of the Foundry. Its gold has not tarnished."},
	{"yeux_fente", "Une lueur blanche, calme, comme celle des veilleurs qui ne dormaient plus.", "A calm white glow, like that of the watchers who no longer slept."},
	{"yeux_ame", "La lumière des pierres qui fonctionnent encore. Elle brille plus fort près d'une Tour qui tient.", "The light of stones that still work. It shines brighter near a Tower that stands."},
	{"yeux_braise", "Le regard de ceux qui ont trop longtemps fixé les creusets de la Fonderie.", "The gaze of those who stared too long into the Foundry's crucibles."},
	{"deco_plume", "Une plume couleur de braise, ramassée près de l'entrée de la caverne la dernière nuit du Long Silence.", "An ember-coloured feather, picked up near the cavern entrance on the last night of the Long Silence."},
	{"deco_plume_ame", "Elle s'allume doucement quand on passe près d'une pierre bien posée.", "It glows softly when you pass near a well-laid stone."},
	{"deco_echarpe", "Tissée de fil d'or par une bâtisseuse, pour reconnaître les siens dans la brume.", "Woven with gold thread by a builder, to find her own people in the mist."},
	{"arme_epee", "Une épée de la lisière, à la garde usée. Elle n'a jamais servi à frapper un gardien : seulement à ouvrir le chemin.", "An edge sword with a worn guard. It never struck a guardian: it only opened the way."},
	{"arme_lance", "Les gardes de la Tour la tenaient droite à l'entrée. La dernière est restée plantée là, seule.", "The Tower guards held it upright at the entrance. The last one stayed planted there, alone."},
	{"arme_marteau", "Il servait à reposer les pierres tombées. Pendant le Long Silence, il en est tombé plus qu'il n'en pouvait reposer.", "It was used to set fallen stones back. During the Long Silence, more fell than it could ever set back."},
	{"arme_fil", "Un fil arraché au Tisseur. Il se tend tout seul quand quelque chose est mal découpé.", "A thread pulled from the Weaver. It goes taut on its own when something is cut wrong."},
	{"main_bouclier", "Un bouclier de chêne, venu d'un temps où des arbres poussaient encore au-dessus de la caverne.", "An oak shield, from a time when trees still grew above the cavern."},
	{"main_braise", "Une braise prise au fourneau tiède. Elle ne s'éteint pas, et elle tient chaud aux mains.", "An ember taken from the lukewarm furnace. It never goes out, and keeps your hands warm."},
	{"fam_moulinette", "Elle passait de rouage en rouage et sentait ce qui clochait. On dit qu'elle revient parfois s'asseoir à côté de ceux qui réparent.", "She went from gear to gear and felt what was wrong. They say she sometimes comes back to sit beside those who repair."},
	{"fam_luciole", "Une luciole née d'une fenêtre de la Tour restée allumée. Elle suit ceux qui rallument les autres.", "A firefly born from a Tower window that stayed lit. It follows those who light the others again."},
	{"fam_rouage", "Un petit rouage tombé d'une horloge de la Cité, qui a appris à rouler tout seul pour retrouver sa place.", "A small gear fallen from a City clock, which learned to roll on its own to find its place again."},
	{"fam_corbeau", "Les corbeaux de la Cité volaient entre les étages. Celui-ci a vu tout le Long Silence et n'en dit rien.", "The City crows flew between the floors. This one saw the whole Long Silence and says nothing."},
	{"aura_spores", "Les spores des mousses de la caverne, qui s'allument au passage de ce qui fonctionne.", "Spores from the cavern moss, which light up when something that works passes by."},
	{"aura_braises", "Des braises échappées de la Fonderie, qui ont continué de flotter sans jamais retomber.", "Embers that escaped the Foundry and kept floating, never coming down."},
	{"aura_brume", "La brume des fuites, apprivoisée. Elle suit son porteur au lieu de s'échapper des murs.", "The mist of the leaks, tamed. It follows its bearer instead of escaping from the walls."},
	{"fond_astro", "Après le voyageur, la fissure a encore laissé passer un morceau de ciel : une plaine grise, et une planète bleue au-dessus.", "After the traveller, the crack let through one more piece of sky: a grey plain, and a blue planet above it."},
	{"arme_astro", "Une clé tombée par la fissure, faite pour serrer des écrous qu'aucun mécanisme de la Cité ne possède.", "A wrench that fell through the crack, made to tighten bolts that no City mechanism has."},
	{"main_astro", "Un petit drapeau planté sur une corniche. Il porte le même nombre que les affaires du voyageur.", "A small flag planted on a ledge. It bears the same number as the traveller's belongings."},
	{"fam_astro", "Il tourne au-dessus des ruines en clignotant, comme s'il attendait une réponse d'en haut.", "It circles above the ruins, blinking, as if waiting for an answer from above."},
	{"aura_astro", "Des bulles qui ne tombent pas. Ici, quelque chose a oublié ce que voulait dire le poids.", "Bubbles that never fall. Here, something forgot what weight meant."},
	{"yeux_astro", "Un regard bleu et calme, celui de quelqu'un qui a déjà vu la Cité d'en haut.", "A calm blue gaze, that of someone who has already seen the City from above."},
	{"casque_astro", "Un casque fermé, à visière dorée. Il a gardé à l'intérieur un air qui ne vient pas de la caverne.", "A sealed helmet with a golden visor. It kept inside an air that does not come from the cavern."},
	{"armure_astro", "Une combinaison blanche couverte de boutons. Les veilleurs n'ont jamais trouvé à quoi servait le rouge.", "A white suit covered in buttons. The watchers never found out what the red one was for."},
	{"jambes_astro", "Des jambières lourdes, faites pour marcher là où rien ne retient au sol.", "Heavy leggings, made to walk where nothing holds you to the ground."},
	{"cape_astro", "Un sac qui siffle doucement. Il contient de l'air d'ailleurs, et personne n'a osé l'ouvrir.", "A pack that hisses softly. It holds air from elsewhere, and no one dared open it."},
	{"deco_astro", "Une antenne au voyant rouge. Elle clignote plus vite quand on regarde vers la fissure.", "An antenna with a red light. It blinks faster when you look toward the crack."},
	{"fond_neon", "Une nuit violette, un soleil rayé, une grille qui file vers l'horizon. Rien de tout cela n'existe sous la surface.", "A violet night, a striped sun, a grid running to the horizon. None of it exists below the surface."},
	{"arme_neon", "Un sabre de lumière rose. Il ne coupe rien, mais il éclaire mieux que n'importe quelle lanterne.", "A sabre of pink light. It cuts nothing, but it shines better than any lantern."},
	{"main_neon", "Une radio tombée par la fissure, qui joue encore une musique que personne ici ne connaît.", "A radio that fell through the crack, still playing music no one here knows."},
	{"fam_neon", "Un chat fait seulement de lumière. Moulinette l'a regardé longtemps, puis l'a laissé passer.", "A cat made only of light. Moulinette watched it for a long time, then let it pass."},
	{"aura_neon", "Des lueurs roses et bleues, qui grésillent un peu, comme une enseigne fatiguée.", "Pink and blue glows that crackle a little, like a tired sign."},
	{"yeux_neon", "Un regard rose, qui ne cligne pas.", "A pink gaze that does not blink."},
	{"casque_neon", "Des lunettes larges et une crête de lumière. Celui qui les portait ne voulait pas passer inaperçu.", "Wide shades and a crest of light. Whoever wore them did not want to go unnoticed."},
	{"armure_neon", "Un blouson cousu de fils lumineux. Dans la brume, on le voit avant de voir celui qui le porte.", "A jacket sewn with glowing threads. In the mist, you see it before you see the wearer."},
	{"jambes_neon", "Un pantalon zébré de lumière bleue, fait pour être vu de loin.", "Trousers striped with blue light, made to be seen from afar."},
	{"cape_neon", "Un long manteau dont l'ourlet brille. Il laisse une trace claire derrière chaque pas.", "A long coat with a glowing hem. It leaves a bright trail behind every step."},
	{"deco_neon", "Une crête rose qui grésille au-dessus du casque.", "A pink crest that crackles above the helmet."},
	{"fond_cyber", "Une ville sous la pluie, avec des fenêtres allumées partout. Les veilleurs l'ont vue une seule fois, au fond de la fissure.", "A city in the rain, with lit windows everywhere. The watchers saw it only once, at the bottom of the crack."},
	{"arme_cyber", "Une lame au fil vert. Elle bourdonne doucement quand elle s'approche d'un mécanisme déréglé.", "A green-edged blade. It hums softly when it nears a broken mechanism."},
	{"main_cyber", "Une tablette qui affiche des lignes qui défilent. Personne ne sait les lire, mais elles ne s'arrêtent jamais.", "A tablet showing scrolling lines. No one can read them, but they never stop."},
	{"fam_cyber", "Un drone à l'œil rouge. Il observe la Cité comme s'il en faisait le relevé pour quelqu'un.", "A red-eyed drone. It watches the City as if surveying it for someone."},
	{"aura_cyber", "Des carrés de lumière verte qui apparaissent et disparaissent, comme une image qui se recharge.", "Squares of green light that appear and vanish, like a picture reloading."},
	{"yeux_cyber", "Un regard vert et précis, qui trouve les fissures avant qu'elles ne s'ouvrent.", "A sharp green gaze that finds cracks before they open."},
	{"casque_cyber", "Une capuche à visière verte. On n'y voit jamais le visage, seulement la lumière.", "A hood with a green visor. You never see the face, only the light."},
	{"armure_cyber", "Une veste parcourue de lignes vertes, comme si un circuit avait poussé dans le tissu.", "A jacket lined with green tracks, as if a circuit had grown into the fabric."},
	{"jambes_cyber", "Un pantalon à poches et à genouillères jaunes, fait pour courir et grimper.", "Trousers with pockets and yellow knee pads, made to run and climb."},
	{"cape_cyber", "Un long manteau gris au bord vert, mouillé d'une pluie qui ne tombe pas ici.", "A long grey coat with a green edge, wet from a rain that does not fall here."},
	{"deco_cyber", "Une antenne d'oreille qui capte des voix lointaines. Elles parlent toutes en même temps.", "An ear antenna that picks up distant voices. They all talk at once."},
	{"fond_fou", "Une scène aux rideaux violets, dressée on ne sait quand au milieu de la Cité. Personne n'y a jamais joué.", "A stage with violet curtains, set up who knows when in the middle of the City. No one ever performed on it."},
	{"cape_fou", "Une cape à losanges, recousue tant de fois que les couleurs ne se suivent plus.", "A diamond-patterned cape, mended so many times the colours no longer line up."},
	{"jambes_fou", "Une jambe violette, une jambe dorée, et des souliers pointus qui tintent à chaque pas.", "One violet leg, one golden leg, and pointed shoes that jingle at every step."},
	{"armure_fou", "Un pourpoint à grelots. Pendant le Long Silence, c'était le seul bruit joyeux de la Cité.", "A doublet with bells. During the Long Silence, it was the only cheerful sound in the City."},
	{"casque_fou", "Le bonnet du Fou, à trois pointes. Il paraît qu'il rit tout seul quand quelqu'un se trompe.", "The Fool's three-pointed cap. They say it laughs to itself when someone gets it wrong."},
	{"yeux_fou", "Un regard qui pétille. Il ne se moque pas : il a juste déjà vu l'erreur arriver.", "A twinkling gaze. It is not mocking: it just saw the mistake coming."},
	{"deco_fou", "Un grelot d'or, le plus clair de tous. On l'entend même au fond du Puits.", "A golden bell, the clearest of all. You can hear it even at the bottom of the Well."},
	{"arme_fou", "Une marotte, un bâton coiffé d'une petite tête. Elle a toujours le dernier mot.", "A bauble, a stick topped with a little head. It always has the last word."},
	{"main_fou", "Un masque de comédie au sourire figé. On le portait pour dire les choses que personne ne voulait entendre.", "A comedy mask with a fixed smile. It was worn to say what no one wanted to hear."},
	{"fam_fou", "Une boîte qui s'ouvre quand on ne s'y attend plus. Le petit fou à ressort n'a jamais raté son effet.", "A box that opens when you no longer expect it. The little spring fool never missed its moment."},
	{"aura_fou", "Des éclats de rire en lumière violette, qui restent un peu après que le rire s'est tu.", "Bursts of laughter in violet light, lingering a little after the laughing stops."},
	{"fond_carnaval", "Une nuit de guirlandes et de confettis. La fissure l'a laissée tomber d'un coup, toute la fête avec.", "A night of garlands and confetti. The crack dropped it all at once, party included."},
	{"cape_carnaval", "Une cape bordée de plumes de toutes les couleurs. Elle laisse une traînée de couleurs dans la brume.", "A cape trimmed with feathers of every colour. It leaves a trail of colour in the mist."},
	{"jambes_carnaval", "Des collants rayés rouge et jaune, impossibles à confondre avec quoi que ce soit d'autre.", "Red and yellow striped tights, impossible to mistake for anything else."},
	{"armure_carnaval", "Un corsage vert couvert de paillettes. Il renvoie la moindre lueur de lanterne.", "A green bodice covered in sequins. It throws back the faintest lantern light."},
	{"casque_carnaval", "Un masque doré à losanges. Derrière, on peut être n'importe qui.", "A golden diamond-patterned mask. Behind it, you can be anyone."},
	{"yeux_carnaval", "Un regard doré, qui ne laisse rien deviner.", "A golden gaze that gives nothing away."},
	{"deco_carnaval", "Un panache de trois plumes, rouge, bleu et vert. Il danse même quand on reste immobile.", "A crest of three plumes, red, blue and green. It dances even when you stand still."},
	{"arme_carnaval", "Un bâton à rubans qui tournoient. Il ne fait peur à personne, et c'est voulu.", "A stick with twirling ribbons. It scares no one, and that is the point."},
	{"main_carnaval", "Des maracas qui gardent le rythme d'une fête finie depuis longtemps.", "Maracas that keep the beat of a party that ended long ago."},
	{"fam_carnaval", "Un perroquet qui répète les mots qu'il entend. Pendant le Long Silence, il n'a rien appris.", "A parrot that repeats the words it hears. During the Long Silence, it learned nothing."},
	{"aura_carnaval", "Des confettis qui ne finissent jamais de tomber.", "Confetti that never finishes falling."},
	{"fond_cirque", "Un chapiteau rayé rouge et blanc, planté dans la poussière de la caverne. La piste attend encore.", "A red and white striped big top, pitched in the cavern dust. The ring is still waiting."},
	{"cape_cirque", "Une queue-de-pie rouge bordée d'or. Elle faisait taire la salle avant chaque numéro.", "A red tailcoat trimmed with gold. It silenced the crowd before every act."},
	{"jambes_cirque", "Une culotte blanche et des bottes noires cirées, faites pour tenir le centre de la piste.", "White breeches and polished black boots, made to hold the centre of the ring."},
	{"armure_cirque", "Une veste rouge à brandebourgs dorés, cousue pour quelqu'un qui n'avait jamais peur.", "A red jacket with golden frogging, sewn for someone who was never afraid."},
	{"casque_cirque", "Un haut-de-forme noir à ruban rouge. On en sort parfois des choses qu'on n'y a pas mises.", "A black top hat with a red band. Sometimes things come out of it that were never put in."},
	{"yeux_cirque", "Un regard sûr, qui ne quitte jamais la bête des yeux.", "A steady gaze that never takes its eyes off the beast."},
	{"deco_cirque", "Une grande plume rouge, pour qu'on voie le dompteur du dernier rang.", "A tall red plume, so the tamer can be seen from the back row."},
	{"arme_cirque", "Un fouet qui claque sans jamais toucher. Il sert à donner le signal, pas à punir.", "A whip that cracks without ever touching. It gives the signal; it does not punish."},
	{"main_cirque", "Un cerceau doré. On l'a vu traverser des choses beaucoup plus dangereuses que lui.", "A golden hoop. It has been seen going through things far more dangerous than itself."},
	{"fam_cirque", "Un phoque qui tient un ballon en équilibre depuis le début du Long Silence. Il ne l'a jamais fait tomber.", "A seal that has balanced a ball since the start of the Long Silence. It never dropped it."},
	{"aura_cirque", "Des paillettes de piste qui flottent dans la lumière des projecteurs.", "Ring sparkles floating in the spotlight."},
	{"fond_labo", "Un laboratoire aux étagères pleines de fioles qui bouillonnent seules. Personne ne sait ce qu'on y cherchait.", "A laboratory whose shelves are full of flasks bubbling on their own. No one knows what was being sought there."},
	{"cape_labo", "Une blouse longue, tachée de tout ce qui a mal tourné.", "A long lab coat, stained by everything that went wrong."},
	{"jambes_labo", "Un pantalon de laine et des pantoufles rouges. On ne quitte pas son laboratoire pour si peu.", "Wool trousers and red slippers. You do not leave your laboratory for so little."},
	{"armure_labo", "Une blouse aux poches pleines de crayons. Une tache verte refuse de partir.", "A lab coat with pockets full of pencils. One green stain refuses to come out."},
	{"casque_labo", "Des cheveux dressés par l'électricité et de grosses lunettes. Une expérience a très bien marché, ou très mal.", "Hair standing on end from electricity, and big goggles. An experiment went very well, or very badly."},
	{"yeux_labo", "Un regard vert, celui de quelqu'un qui vient d'avoir une idée.", "A green gaze, that of someone who has just had an idea."},
	{"deco_labo", "Des étincelles qui crépitent au-dessus de la tête, sans jamais rien brûler.", "Sparks crackling above the head, never burning anything."},
	{"arme_labo", "Une bobine électrique qui siffle. Elle a rallumé une fenêtre de la Tour, une fois, par accident.", "A hissing electric coil. It once lit a Tower window again, by accident."},
	{"main_labo", "Une fiole verte qui bouillonne sans feu. Il ne faut surtout pas la boire.", "A green flask bubbling without fire. Above all, do not drink it."},
	{"fam_labo", "Un cerveau dans un bocal. Il réfléchit beaucoup, et ne dit jamais à quoi.", "A brain in a jar. It thinks a lot, and never says what about."},
	{"aura_labo", "Des bulles qui s'échappent des fioles et montent sans fin.", "Bubbles escaping from the flasks and rising forever."},
	{"fond_chapelier", "Une table de goûter dressée pour un thé qui ne finit jamais. Les tasses sont toujours pleines.", "A tea table set for a tea that never ends. The cups are always full."},
	{"cape_chapelier", "Un habit vert à carreaux dorés, porté par quelqu'un qui avait toujours un rendez-vous.", "A green coat with golden checks, worn by someone who always had an appointment."},
	{"jambes_chapelier", "Un pantalon en damier, noir et blanc, impossible à porter sans avoir l'air pressé.", "Black and white checkerboard trousers, impossible to wear without looking in a hurry."},
	{"armure_chapelier", "Un gilet rose à nœud bleu, avec une chaîne de montre qui ne mène à aucune montre.", "A pink waistcoat with a blue bow, and a watch chain that leads to no watch."},
	{"casque_chapelier", "Un chapeau démesuré, orné d'une carte marquée d'un point d'interrogation. La question n'a jamais été posée.", "A towering hat with a card marked with a question mark. The question was never asked."},
	{"yeux_chapelier", "Un regard qui pétille, comme si on venait de lui raconter une devinette.", "A sparkling gaze, as if someone had just told it a riddle."},
	{"deco_chapelier", "Une fleur rose piquée au chapeau. Elle ne fane pas, elle attend.", "A pink flower pinned to the hat. It does not wilt; it waits."},
	{"arme_chapelier", "Un parapluie toujours fermé. Il ne pleut jamais dans la Cité, mais on ne sait jamais.", "An umbrella that is always closed. It never rains in the City, but you never know."},
	{"main_chapelier", "Une théière qui verse un thé toujours chaud. Personne ne l'a jamais remplie.", "A teapot that always pours hot tea. No one ever filled it."},
	{"fam_chapelier", "Un oiseau mécanique qu'il faut remonter. Il chante l'heure du thé, à n'importe quelle heure.", "A clockwork bird that needs winding. It sings teatime at any time."},
	{"aura_chapelier", "Une vapeur de thé qui flotte en spirales et sent la cannelle.", "A tea steam that floats in spirals and smells of cinnamon."},
	{"fond_pierrot", "Une ruelle sous une pluie fine, éclairée par une seule lune. Elle est tombée par la fissure un soir de tristesse.", "An alley under a light rain, lit by a single moon. It fell through the crack one sad evening."},
	{"cape_pierrot", "Une cape bleue de pluie, toujours un peu humide, qui ne sèche jamais vraiment.", "A blue rain cape, always slightly damp, which never really dries."},
	{"jambes_pierrot", "Un pantalon blanc bouffant à pompons noirs, fait pour danser même quand on n'en a pas envie.", "Baggy white trousers with black pompoms, made for dancing even when you do not feel like it."},
	{"armure_pierrot", "Une blouse blanche à collerette et gros boutons noirs. Elle ne va bien qu'aux gens tristes.", "A white ruffled blouse with big black buttons. It only suits sad people."},
	{"casque_pierrot", "Un visage blanc avec une larme peinte. Celui qui le porte ne pleure plus : la larme le fait pour lui.", "A white face with a painted tear. Whoever wears it cries no more: the tear does it for them."},
	{"yeux_pierrot", "Un regard bleu et mouillé, qui regarde toujours un peu plus loin que les autres.", "A wet blue gaze, always looking a little farther than others."},
	{"deco_pierrot", "Une fleur fanée piquée sur la tête. Elle était belle, une fois.", "A wilted flower pinned to the head. It was beautiful, once."},
	{"arme_pierrot", "Une rose sans épines. Elle ne fait de mal à personne, pas même à celui qui la tient.", "A thornless rose. It hurts no one, not even the one holding it."},
	{"main_pierrot", "Un ballon rouge dégonflé, gardé quand même. On ne jette pas ce qui a volé haut.", "A deflated red balloon, kept anyway. You do not throw away what once flew high."},
	{"fam_pierrot", "Un pigeon gris qui suit les gens tristes, sans jamais les déranger.", "A grey pigeon that follows sad people, never bothering them."},
	{"aura_pierrot", "Une petite pluie qui ne tombe que sur son porteur.", "A light rain that falls only on its bearer."},
	{"fond_cuisine", "Une cuisine carrelée, avec des casseroles encore chaudes. Elle est tombée par la fissure à l'heure du repas.", "A tiled kitchen with pots still warm. It fell through the crack at mealtime."},
	{"cape_cuisine", "Un torchon à carreaux rouges, noué en cape. Il a essuyé beaucoup de casseroles et quelques larmes.", "A red checked tea towel tied as a cape. It has dried many pots and a few tears."},
	{"jambes_cuisine", "Un pantalon pied-de-poule et des sabots blancs, pour tenir debout toute une soirée de service.", "Houndstooth trousers and white clogs, to stay on your feet through a whole evening service."},
	{"armure_cuisine", "Une veste de chef à double boutonnage, toujours blanche malgré tout.", "A double-breasted chef's jacket, still white despite everything."},
	{"casque_cuisine", "Une toque haute et plissée. Plus elle est haute, plus on écoute celui qui la porte.", "A tall pleated chef's hat. The taller it is, the more people listen to the wearer."},
	{"yeux_cuisine", "Un regard gourmand, qui sait déjà ce qui mijote.", "A hungry gaze that already knows what is simmering."},
	{"deco_cuisine", "Une moustache en guidon, frisée aux deux bouts. Elle frémit quand quelque chose brûle.", "A handlebar moustache, curled at both ends. It twitches when something is burning."},
	{"arme_cuisine", "Une louche qui a goûté toutes les soupes de la Cité. Elle en garde le souvenir.", "A ladle that tasted every soup in the City. It remembers them all."},
	{"main_cuisine", "Une poêle noire et lourde. Elle arrête mieux les coups que bien des boucliers.", "A heavy black frying pan. It blocks blows better than many shields."},
	{"fam_cuisine", "Un homard qui a échappé à la marmite et ne l'a jamais oublié.", "A lobster that escaped the pot and never forgot it."},
	{"aura_cuisine", "Une vapeur de marmite qui sent bon et réchauffe ceux qui passent.", "Pot steam that smells good and warms whoever walks by."},
	{"fond_chambre", "Une chambre de nuit, avec une lune à la fenêtre. Elle est tombée par la fissure pendant que quelqu'un dormait.", "A bedroom at night, with a moon in the window. It fell through the crack while someone was asleep."},
	{"cape_chambre", "Un plaid à carreaux, chaud et un peu râpé. Il a couvert beaucoup de nuits blanches.", "A checked plaid blanket, warm and a little worn. It covered many sleepless nights."},
	{"jambes_chambre", "Un bas de pyjama à pois et des chaussons lapin. On ne court pas avec, et c'est très bien comme ça.", "Polka-dot pyjama bottoms and bunny slippers. You do not run in them, and that is fine."},
	{"armure_chambre", "Un haut de pyjama bleu à pois blancs. Il ne protège de rien, sauf du froid.", "A blue pyjama top with white dots. It protects from nothing, except the cold."},
	{"casque_chambre", "Un bonnet de nuit à pompon. Celui qui le porte n'a plus envie de se battre, seulement de dormir.", "A nightcap with a pompom. Whoever wears it no longer wants to fight, only to sleep."},
	{"yeux_chambre", "Des yeux fermés. Ils ne dorment pas vraiment : ils écoutent.", "Closed eyes. They are not really asleep: they are listening."},
	{"deco_chambre", "Un masque de nuit rose, remonté sur le front. On ne sait jamais quand on aura besoin de dormir.", "A pink sleep mask pushed up on the forehead. You never know when you will need to sleep."},
	{"arme_chambre", "Un oreiller. Le combat le plus doux de la Cité, et le seul qui finit toujours en rire.", "A pillow. The softest fight in the City, and the only one that always ends in laughter."},
	{"main_chambre", "Un doudou ours, un peu usé aux oreilles. Il a vu tous les cauchemars et n'a jamais eu peur.", "A teddy bear, worn a little at the ears. It saw every nightmare and was never afraid."},
	{"fam_chambre", "Un mouton tout rond, à compter quand le sommeil ne vient pas. On n'arrive jamais au bout.", "A round little sheep to count when sleep will not come. You never reach the end."},
	{"aura_chambre", "Des rêves bleus qui flottent autour de la tête et disparaissent au réveil.", "Blue dreams floating around the head, gone on waking."},
	{"fond_bain", "Une salle de bain carrelée, pleine de bulles. Elle est tombée par la fissure, l'eau encore tiède.", "A tiled bathroom full of bubbles. It fell through the crack, the water still warm."},
	{"cape_bain", "Une serviette de bain rose à rayures, douce et un peu trop grande.", "A pink striped bath towel, soft and a little too big."},
	{"jambes_bain", "Des bottes jaunes et un short bleu, prêts pour une flaque qui n'existe pas ici.", "Yellow boots and blue shorts, ready for a puddle that does not exist here."},
	{"armure_bain", "Une bouée en forme de canard, gonflée pour flotter sur une eau qu'on attend encore.", "A duck-shaped float, blown up to float on water that is still awaited."},
	{"casque_bain", "Une tête de canard jaune au bec orange. Elle ne fait pas peur, mais elle fait réfléchir.", "A yellow duck head with an orange beak. It is not scary, but it makes you think."},
	{"yeux_bain", "Deux yeux ronds et noirs, qui regardent tout avec le même calme.", "Two round black eyes that look at everything with the same calm."},
	{"deco_bain", "Un caneton perché sur la tête, qui refuse de descendre.", "A duckling perched on the head, refusing to come down."},
	{"arme_bain", "Une longue brosse de bain. Elle frotte tout, même ce qui ne voulait pas être frotté.", "A long bath brush. It scrubs everything, even what did not want to be scrubbed."},
	{"main_bain", "Une savonnette rose qui glisse toujours au mauvais moment.", "A pink bar of soap that always slips at the wrong moment."},
	{"fam_bain", "Un canard en caoutchouc. On dit qu'il aide à comprendre une erreur quand on la lui explique à voix haute.", "A rubber duck. They say it helps you understand a mistake when you explain it out loud to it."},
	{"aura_bain", "Des bulles de savon qui éclatent en silence.", "Soap bubbles that pop in silence."},
	{"fond_marche", "Un étal de marché sous un auvent rayé. Les fruits sont tombés par la fissure, encore frais.", "A market stall under a striped awning. The fruit fell through the crack, still fresh."},
	{"cape_marche", "Une grande feuille de bananier, assez large pour s'abriter de la brume.", "A big banana leaf, wide enough to shelter from the mist."},
	{"jambes_marche", "Un pantalon vert rayé comme une écorce de pastèque.", "Green trousers striped like a watermelon rind."},
	{"armure_marche", "Une armure taillée dans une pastèque, rouge et semée de pépins.", "Armour carved from a watermelon, red and scattered with seeds."},
	{"casque_marche", "Un casque en ananas, avec sa couronne de feuilles. Il pique un peu, mais il sent bon.", "A pineapple helmet, with its crown of leaves. It prickles a little, but it smells nice."},
	{"yeux_marche", "Deux yeux noirs comme des pépins.", "Two eyes as black as pips."},
	{"deco_marche", "Deux cerises accrochées au casque, toujours brillantes.", "Two cherries hanging from the helmet, always shiny."},
	{"arme_marche", "Une épée banane, courbe et jaune. Elle ne tranche rien, mais elle se mange en cas de besoin.", "A banana sword, curved and yellow. It cuts nothing, but it can be eaten if needed."},
	{"main_marche", "Un bouclier taillé dans une orange. Il sent bon même après les coups.", "A shield cut from an orange. It still smells good after the blows."},
	{"fam_marche", "Une fraise qui a des yeux et qui suit son porteur. Elle ne mûrit plus, elle vit.", "A strawberry with eyes that follows its bearer. It no longer ripens; it lives."},
	{"aura_marche", "Des gouttes de jus qui flottent et brillent comme des fruits confits.", "Drops of juice that float and shine like candied fruit."},
	{"fond_grenier", "Un grenier plein de cartons, tombés par la fissure avec tout ce qu'on n'osait pas jeter.", "An attic full of boxes, fallen through the crack with everything no one dared throw away."},
	{"cape_grenier", "Une cape en papier journal. On peut y lire des nouvelles d'un monde qui n'est pas celui-ci.", "A newspaper cape. You can read news from a world that is not this one."},
	{"jambes_grenier", "Des jambières faites de tubes en carton empilés. Elles tiennent, et c'est déjà beaucoup.", "Greaves made of stacked cardboard tubes. They hold, and that is already a lot."},
	{"armure_grenier", "Une armure en carton marquée « FRAGILE ». C'est honnête, au moins.", "Cardboard armour marked \"FRAGILE\". At least it is honest."},
	{"casque_grenier", "Une boîte en carton sur la tête, avec des yeux dessinés au feutre. Personne ne la reconnaît, et c'est l'idée.", "A cardboard box on the head, with eyes drawn in marker. No one recognises the wearer, and that is the idea."},
	{"yeux_grenier", "Des yeux dessinés au feutre, un peu de travers, mais pleins de bonne volonté.", "Eyes drawn in marker, a little crooked, but full of good will."},
	{"deco_grenier", "Un cintre tordu en antenne. Il capte surtout le courant d'air.", "A coat hanger bent into an antenna. Mostly it picks up the draught."},
	{"arme_grenier", "Une épée en rouleau d'essuie-tout. Elle plie mais ne rompt pas.", "A paper-towel-roll sword. It bends but does not break."},
	{"main_grenier", "Un couvercle de poubelle en guise de bouclier. Il a déjà servi, et ça se voit.", "A bin lid used as a shield. It has seen use, and it shows."},
	{"fam_grenier", "Un chat qui s'est installé dans un carton et refuse d'en sortir. C'est lui qui a choisi.", "A cat that settled into a box and refuses to come out. It was the cat's choice."},
	{"aura_grenier", "Des bouts de scotch qui flottent et se collent à tout.", "Bits of tape that float and stick to everything."},
	{"fond_chantier", "Un chantier interdit, avec cônes et barrières. Il est tombé par la fissure avant que quelqu'un ne dise que c'était une mauvaise idée.", "A forbidden building site, with cones and barriers. It fell through the crack before anyone said it was a bad idea."},
	{"cape_chantier", "Une bâche bleue nouée en cape. Elle fait beaucoup de bruit dans le moindre courant d'air.", "A blue tarp tied as a cape. It makes a lot of noise in the slightest draught."},
	{"jambes_chantier", "Une chaussette rayée d'un côté, une palme de l'autre. Il n'y avait plus le choix.", "A striped sock on one side, a flipper on the other. There was no choice left."},
	{"armure_chantier", "Un gilet fluo, pour être vu de loin. Dans la caverne, c'est utile, malgré tout.", "A hi-vis vest, to be seen from afar. In the cavern, it is useful, all the same."},
	{"casque_chantier", "Un cône de chantier posé sur la tête. Ça a commencé comme une blague.", "A traffic cone on the head. It started as a joke."},
	{"yeux_chantier", "Un regard perdu, qui se demande encore comment on en est arrivé là.", "A lost gaze, still wondering how it came to this."},
	{"deco_chantier", "Une hélice sur le sommet du cône. Elle tourne, mais elle ne fait pas voler.", "A propeller on top of the cone. It spins, but it does not make you fly."},
	{"arme_chantier", "Un parapluie retourné par un coup de vent qui n'aurait pas dû souffler sous terre.", "An umbrella turned inside out by a gust that should never have blown underground."},
	{"main_chantier", "Une chaise pliante, tenue comme un bouclier. Elle se replie parfois au pire moment.", "A folding chair held like a shield. It sometimes folds at the worst moment."},
	{"fam_chantier", "Un grille-pain avec des ailes. Personne ne sait comment il vole, pas même lui.", "A toaster with wings. No one knows how it flies, not even the toaster."},
	{"aura_chantier", "Des étincelles orange d'origine douteuse. Il vaut mieux ne pas chercher.", "Orange sparks of dubious origin. Better not to look into it."},
	{"fond_fete", "Une fête un peu triste, avec des ballons qui ne montent plus. Elle est tombée par la fissure à minuit pile.", "A slightly sad party, with balloons that no longer rise. It fell through the crack at exactly midnight."},
	{"cape_fete", "Un rideau de douche à fleurs, devenu cape faute de mieux.", "A flowery shower curtain, turned into a cape for lack of anything better."},
	{"jambes_fete", "Des collants filés, portés quand même, parce que la fête avait déjà commencé.", "Laddered tights, worn anyway, because the party had already started."},
	{"armure_fete", "Un drap avec deux trous pour les yeux. Un fantôme très sincère.", "A sheet with two eye holes. A very sincere ghost."},
	{"casque_fete", "Une couronne en papier doré, découpée un peu vite. Elle tient avec du scotch.", "A golden paper crown, cut a little too fast. It holds with tape."},
	{"yeux_fete", "Un regard gêné, de quelqu'un qui pensait que ce serait un bal costumé.", "An awkward gaze, from someone who thought it was a costume ball."},
	{"deco_fete", "Un faux nez à moustache, avec des lunettes. Le déguisement le plus courageux de la Cité.", "A fake nose with a moustache and glasses. The bravest disguise in the City."},
	{"arme_fete", "Une baguette en carton surmontée d'une étoile. Elle n'exauce rien, mais elle y croit.", "A cardboard wand topped with a star. It grants nothing, but it believes."},
	{"main_fete", "Une assiette en carton, gardée de la fête comme bouclier.", "A paper plate, kept from the party as a shield."},
	{"fam_fete", "Un chien déguisé en lion, qui fait de son mieux pour rugir.", "A dog dressed as a lion, doing its best to roar."},
	{"aura_fete", "Des confettis tristes, qui tombent lentement et sans bruit.", "Sad confetti, falling slowly and silently."},
	{"main_lanterne", "Elle s'alluma seule, la nuit où le Long Silence prit fin. Personne ne l'avait remplie. Elle brûle de ce qui fonctionne encore.", "It lit up by itself on the night the Long Silence ended. No one had filled it. It burns with whatever still works."},
	{"casque_cabosse", "Chaque bosse est une chute dans la caverne. Celui qui le porte ne l'a jamais redressé : il dit d'où il vient.", "Every dent is a fall in the cavern. Its wearer never hammered it straight: it tells where they come from."},
	{"main_norme", "Les bâtisseurs y notaient comment poser chaque pierre. Pendant le Long Silence, plus personne ne l'ouvrit, et la Tour se mit à pencher.", "The builders wrote in it how to lay each stone. During the Long Silence no one opened it, and the Tower began to lean."},
	{"fond_galactique", "Par une fissure du plafond de la caverne, on vit un jour un ciel sans pierre. Il fut là une nuit, puis la fissure se referma. Le voyageur était passé par là.", "Through a crack in the cavern ceiling, a sky without stone was seen one day. It stayed one night, then the crack closed. The traveller had come through there."},
	{"cape_serviette", "Tombée d'au-dessus de la surface, pliée avec soin, brodée d'un seul nombre : 42. Personne dans la Cité ne sut jamais ce qu'il comptait.", "Fallen from above the surface, carefully folded, embroidered with a single number: 42. No one in the City ever knew what it counted."},
	{"jambes_galactiques", "Un tissu que la brume ne mouillait pas. Les veilleurs les trouvèrent sur une corniche, cousues d'étoiles, comme posées là pour sécher.", "A fabric the mist could not wet. The watchers found them on a ledge, sewn with stars, as if laid out to dry."},
	{"armure_galactique", "Une veste trop légère pour la Cité, avec un insigne doré marqué 42 sur le cœur. Les fondeurs essayèrent de la refondre. Le métal refusa de fondre.", "A jacket too light for the City, with a golden 42 badge over the heart. The founders tried to melt it down. The metal refused to melt."},
	{"casque_bulle", "Une bulle claire, sans soudure. Les cordiers la descendirent dans le Puits pour voir sous l'eau : elle remonta sèche, et pleine d'un air qui n'était pas d'ici.", "A clear bubble without a seam. The rope-walkers lowered it into the Well to see under the water: it came back dry, full of an air that was not from here."},
	{"yeux_etoiles", "On disait que le voyageur voyait dans le noir comme en plein jour. Ceux qui ont porté son regard parlent de points dorés qui ne s'éteignent pas.", "They said the traveller could see in the dark as in daylight. Those who wore this gaze speak of golden dots that never go out."},
	{"deco_antenne", "Une tige fine qui grésillait parfois, la nuit, tournée vers le haut. Personne ne sut ce qu'elle écoutait. Pendant le Long Silence, elle fut la seule à parler.", "A thin rod that crackled at night, pointing upwards. No one knew what it listened to. During the Long Silence, it was the only thing that spoke."},
	{"arme_etoile", "Une lame qui garde la couleur d'un ciel qu'on ne voit pas d'ici. Elle ne coupe pas la pierre. Elle éclaire juste assez pour avancer.", "A blade that keeps the colour of a sky you cannot see from here. It does not cut stone. It shines just enough to keep going."},
	{"main_guide", "Un livre relié que le voyageur avait dû consulter souvent. La plupart des pages sont effacées. Sur la première, en lettres d'or : 42.", "A bound book the traveller must have read often. Most pages are blank now. On the first one, in gold letters: 42."},
	{"fam_sonde", "Un petit appareil rond qui flottait au-dessus des ruines et suivait qui marchait. Il cherchait son maître. Il le cherche encore.", "A small round device that floated above the ruins and followed whoever walked by. It was looking for its owner. It still is."},
	{"aura_etoiles", "Une poussière qui brille sans chaleur. Elle tombait de la fissure par où le voyageur était arrivé, et ne s'est jamais tout à fait posée.", "A dust that shines without warmth. It fell from the crack the traveller came through, and never quite settled."},
	{"casque_moulinette", "Fait à l'image de la gardienne, avant qu'elle ne descende. Qui le porte sent la pierre de travers avant de la voir. Personne ne l'a gardé longtemps.", "Made in the image of the guardian, before she went down. Whoever wears it feels the crooked stone before seeing it. No one has kept it long."}
};

const int	g_nhistoires = 230;

const char	*item_histoire(int i)
{
	int	k;

	if (i < 0 || i >= g_nitems)
		return (NULL);
	for (k = 0; k < g_nhistoires; k++)
		if (!strcmp(g_histoires[k].id, g_items[i].id))
			return (L(g_histoires[k].fr, g_histoires[k].en));
	return (NULL);
}
